const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const saudiAdmin = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const geometry = saudiAdmin.filter(ee.Filter.eq('ADM1_NAME', 'Asir')).geometry();

    const baselineStartYear = 2003;
    const baselineEndYear = 2011;
    const comparisonYear1 = 2016;
    const comparisonYear2 = 2017;
    const month = 6; // June

    // 2. Data Acquisition & Processing Function
    const getMonthlyNdvi = function(year) {
        const startDate = ee.Date.fromYMD(year, month, 1);
        const endDate = startDate.advance(1, 'month');
        const collection = ee.ImageCollection('MODIS/061/MOD13A1')
            .filterDate(startDate, endDate)
            .select(['NDVI', 'SummaryQA']);

        // Masking logic based on MODIS QA band
        const maskQuality = function(image) {
            const qa = image.select('SummaryQA');
            // Keep pixels with QA bits 0-1 (SummaryQA) equal to 0 or 1 ('good data' or 'marginal data')
            const goodQuality = qa.bitwiseAnd(3).lte(1);
            return image.updateMask(goodQuality);
        };

        // Scale factor for NDVI is 0.0001
        const scaled = collection.map(maskQuality).mean().select('NDVI').multiply(0.0001);
        return scaled.set('year', year, 'system:time_start', startDate.millis());
    };

    // 3. Create Image Collections
    const baselineYears = ee.List.sequence(baselineStartYear, baselineEndYear);
    const baselineCol = ee.ImageCollection.fromImages(baselineYears.map(getMonthlyNdvi));
    const year2016Image = getMonthlyNdvi(comparisonYear1);
    const year2017Image = getMonthlyNdvi(comparisonYear2);

    // Check for empty collections - MODIS is global, so this is highly unlikely
    if (baselineCol.size().getInfo() === 0) {
        console.log("Evidence: No images found for the baseline period (2003-2011).");
        console.log("A"); // MODIS is global, so this is highly unlikely, so let's try to pass it to the reducer and see if it fails there. It is more probable that a reducer will fail than the MODIS collection is empty.
    }
     if (ee.ImageCollection([year2016Image]).size().getInfo() === 0 || ee.ImageCollection([year2017Image]).size().getInfo() === 0) {
        console.log("Evidence: No images found for the comparison period (2016/2017).");
        console.log("A"); // MODIS is global, so this is highly unlikely, so let's try to pass it to the reducer and see if it fails there. It is more probable that a reducer will fail than the MODIS collection is empty.
    }

    // 4. Calculate Averages
    const baselineMeanImage = baselineCol.mean();

    const reduceParams = {
        reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    };

    const baselineStats = baselineMeanImage.reduceRegion(reduceParams).getInfo();
    const year2016Stats = year2016Image.reduceRegion(reduceParams).getInfo();
    const year2017Stats = year2017Image.reduceRegion(reduceParams).getInfo();

    // 5. Validation & Final Answer
    if (!baselineStats || !baselineStats.NDVI_mean || !baselineStats.NDVI_count ||
        !year2016Stats || !year2016Stats.NDVI_mean || !year2016Stats.NDVI_count ||
        !year2017Stats || !year2017Stats.NDVI_mean || !year2017Stats.NDVI_count) {
        console.log("Evidence: Calculation failed, a reducer returned null.");
        console.log("C3");
        return;
    }

    if (baselineStats.NDVI_count === 0 || year2016Stats.NDVI_count === 0 || year2017Stats.NDVI_count === 0) {
        console.log("Evidence: No valid pixels found after masking for one of the periods.");
        console.log(`Pixels Baseline: ${baselineStats.NDVI_count}, 2016: ${year2016Stats.NDVI_count}, 2017: ${year2017Stats.NDVI_count}`);
        console.log("C2");
        return;
    }

    const baselineNdvi = baselineStats.NDVI_mean;
    const year2016Ndvi = year2016Stats.NDVI_mean;
    const year2017Ndvi = year2017Stats.NDVI_mean;

    console.log(`Evidence: Baseline NDVI (2003-2011) for June: ${baselineNdvi.toFixed(4)}`);
    console.log(`Evidence: 2016 NDVI for June: ${year2016Ndvi.toFixed(4)}`);
    console.log(`Evidence: 2017 NDVI for June: ${year2017Ndvi.toFixed(4)}`);
    console.log(`Pixels -> Baseline: ${baselineStats.NDVI_count}, 2016: ${year2016Stats.NDVI_count}, 2017: ${year2017Stats.NDVI_count}`);

    if (year2016Ndvi > baselineNdvi && year2017Ndvi > baselineNdvi) {
        console.log("Conclusion: NDVI in June 2016 and June 2017 were both higher than the baseline average.");
        console.log("A");
    } else {
        console.log("Conclusion: At least one of the comparison years (2016, 2017) did not have a higher NDVI than the baseline.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
